CREATE TABLE IF NOT EXISTS clients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT, company TEXT, email TEXT, platform TEXT, status TEXT DEFAULT 'Active', created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT, client_id UUID REFERENCES clients(id) ON DELETE SET NULL, platform TEXT, status TEXT DEFAULT 'NEW', priority TEXT DEFAULT 'MEDIUM', due_date DATE, created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS requirements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT, description TEXT, project_id UUID REFERENCES projects(id) ON DELETE SET NULL, category TEXT, priority TEXT, status TEXT DEFAULT 'OPEN', created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT, description TEXT, project_id UUID REFERENCES projects(id) ON DELETE SET NULL, status TEXT DEFAULT 'TODO', priority TEXT DEFAULT 'MEDIUM', due_date DATE, created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS test_cases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT, description TEXT, project_id UUID REFERENCES projects(id) ON DELETE SET NULL, status TEXT DEFAULT 'NOT_TESTED', created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS test_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), test_case_id UUID REFERENCES test_cases(id) ON DELETE CASCADE, attempt_number INT, status TEXT, actual_result TEXT, failure_reason TEXT, started_at TIMESTAMP DEFAULT now(), completed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS fixes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT, description TEXT, project_id UUID REFERENCES projects(id) ON DELETE SET NULL, status TEXT DEFAULT 'OPEN', priority TEXT DEFAULT 'MEDIUM', root_cause TEXT, created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS enhancements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT, description TEXT, project_id UUID REFERENCES projects(id) ON DELETE SET NULL, status TEXT DEFAULT 'REQUESTED', priority TEXT DEFAULT 'MEDIUM', requested_by TEXT, created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS final_rechecks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID REFERENCES projects(id) ON DELETE CASCADE, status TEXT DEFAULT 'PENDING', reason TEXT, created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS activity_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), action TEXT, entity_type TEXT, entity_id UUID, description TEXT, metadata JSONB, created_at TIMESTAMP DEFAULT now());
